import copy
out = copy.deepcopy(grid)
claimed = [[False]*19 for _ in range(13)]
# Each mapped L pair: bounding box, endpoints (all source-color cells) and target.
pairs = [
    (3, 4, [(5,8),(5,9),(6,8),(7,10),(8,9),(8,10)]),
    (6, 8, [(4,6),(4,7),(5,6),(6,13),(7,12),(7,13)]),
    (7, 1, [(1,6),(1,7),(2,6),(10,8),(11,7),(11,8)]),
    (2, 4, [(6,15),(6,16),(7,16),(9,13),(10,13),(10,14)]),
]
rects=[]
for src,dst,cells in pairs:
    rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    rects.append((src,dst,(r0,r1,c0,c1)))
    preserve=set(cells)
    fill=1 if dst==0 else dst
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if claimed[r][c]:
                continue
            if (r,c) not in preserve:
                out[r][c]=fill
            claimed[r][c]=True
# map the standalone 2x2 color-8 object to color 2
for r in (1,2):
    for c in (1,2):
        out[r][c]=2
print(rects)
for row in out: print(' '.join(map(str,row)))
